.ds-bank-list { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(auto-fill, minmax(250px, 1fr)); gap: var(--space-2); }
.ds-bank-card { width: 100%; height: 100%; text-align: left; display: flex; flex-direction: column; gap: var(--space-1); background: var(--bg); border: 1px solid var(--border-strong); border-radius: var(--radius-s); padding: var(--space-3) var(--space-4); cursor: pointer; font-family: var(--font-sans); font-size: var(--text-m); color: var(--text); }
.ds-bank-card:hover:not(:disabled) { background: var(--surface-hover); }
.ds-bank-card:active:not(:disabled) { background: var(--surface-hover); transform: translateY(1px); }
.ds-bank-card:focus-visible { outline: 2px solid var(--focus-ring); outline-offset: 2px; }
.ds-bank-card:disabled { cursor: default; border-color: var(--border); }
.ds-bank-active { border-color: var(--accent); background: var(--accent-soft); box-shadow: inset 3px 0 0 var(--accent); }
.ds-bank-title { font-weight: 700; display: flex; align-items: center; gap: var(--space-2); flex-wrap: wrap; }
.ds-bank-badge { font-size: var(--text-xs); font-weight: 600; text-transform: uppercase; letter-spacing: 0.06em; color: var(--accent); border: 1px solid var(--accent); border-radius: var(--radius-pill); padding: 0.05em 0.6em; }
.ds-bank-active .ds-bank-badge { color: var(--accent-strong); border-color: var(--accent-strong); }
.ds-bank-card:disabled:not(.ds-bank-active) .ds-bank-badge { color: var(--text-muted); border-color: var(--border); }
.ds-bank-meta { color: var(--text-muted); font-size: var(--text-s); }
.ds-bank-note { color: var(--text-muted); font-size: var(--text-xs); font-style: italic; }
@media (prefers-reduced-motion: no-preference) {
  .ds-bank-card { transition: background var(--dur-quick) var(--ease-out), border-color var(--dur-quick) var(--ease-out), color var(--dur-quick) var(--ease-out), transform 50ms var(--ease-out); }
}

.ds-grid { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(auto-fill, minmax(4.25rem, 1fr)); gap: var(--space-2); }
.ds-tile { position: relative; width: 100%; display: flex; flex-direction: column; align-items: flex-start; gap: 0.1em; text-align: left; background: transparent; border: 1px solid var(--border); border-radius: var(--radius-s); padding: 0.35em 0.5em; cursor: pointer; color: var(--text); }
.ds-tile-viewed { border-color: var(--border-strong); }
.ds-tile:hover:not([aria-current="true"]) { background: var(--surface-hover); }
.ds-tile:active { transform: translateY(1px); }
.ds-tile:focus-visible { outline: 2px solid var(--focus-ring); outline-offset: 2px; }
.ds-tile[aria-current="true"] { background: var(--accent-soft); border-color: var(--accent); box-shadow: inset 3px 0 0 var(--accent); }
.ds-tile-id { font-family: var(--font-mono); font-weight: 700; }
.ds-tile-points { font-family: var(--font-mono); font-size: var(--text-xs); color: var(--text-muted); }
.ds-tile[aria-current="true"] .ds-tile-points { color: var(--accent-strong); }
@media (prefers-reduced-motion: no-preference) {
  .ds-tile { transition: background var(--dur-quick) var(--ease-out), border-color var(--dur-quick) var(--ease-out), color var(--dur-quick) var(--ease-out), transform 50ms var(--ease-out); }
}

.ds-mode-picker { border: 0; padding: 0; margin: var(--space-4) 0 0; display: grid; gap: var(--space-2); font-family: var(--font-sans); font-size: var(--text-m); color: var(--text); }
.ds-mode-picker legend { padding: 0; margin-bottom: var(--space-2); font-size: var(--text-s); font-weight: 600; color: var(--text-muted); }
.ds-mode-option { display: grid; grid-template-columns: auto 1fr; gap: 0 var(--space-2); align-items: baseline; padding: var(--space-2) var(--space-3); border: 1px solid var(--border); border-radius: var(--radius-s); cursor: pointer; }
.ds-mode-option:hover { background: var(--surface-hover); }
.ds-mode-option-on { border-color: var(--accent); background: var(--accent-soft); }
.ds-mode-option input:focus-visible { outline: 2px solid var(--focus-ring); outline-offset: 2px; }
.ds-mode-name { font-weight: 600; }
.ds-mode-blurb { grid-column: 2; color: var(--text-muted); font-size: var(--text-s); }
@media (prefers-reduced-motion: no-preference) {
  .ds-mode-option { transition: background var(--dur-quick) var(--ease-out), border-color var(--dur-quick) var(--ease-out); }
}

.ds-clipboard-label { display: block; margin-top: var(--space-4); font-family: var(--font-sans); font-size: var(--text-s); font-weight: 600; color: var(--text); }
.ds-clipboard-hint { margin: var(--space-1) 0 var(--space-2); font-family: var(--font-sans); color: var(--text-muted); font-size: var(--text-s); }
.ds-clipboard-input { width: 100%; font-family: var(--font-mono); font-size: var(--text-s); background: var(--surface-raised); color: var(--text); border: 1px solid var(--border); border-radius: var(--radius-s); padding: var(--space-2); resize: vertical; }
.ds-clipboard-input:hover { border-color: var(--border-strong); }
.ds-clipboard-input:focus-visible { outline: 2px solid var(--focus-ring); outline-offset: 2px; }
.ds-clipboard-actions { display: flex; justify-content: flex-end; margin-top: var(--space-2); }
.ds-btn { background: var(--surface-raised); border: 1px solid var(--border-strong); color: var(--text); padding: 0.5em 1.1em; border-radius: var(--radius-s); cursor: pointer; font-family: var(--font-sans); font-size: var(--text-m); font-weight: 600; }
.ds-btn:focus-visible { outline: 2px solid var(--focus-ring); outline-offset: 2px; }
.ds-btn-primary { background: var(--accent); border-color: var(--accent); color: var(--accent-contrast); }
.ds-btn-primary:hover { background: var(--accent-strong); border-color: var(--accent-strong); }

.ds-prose { font-family: var(--font-sans); font-size: var(--text-m); line-height: 1.55; color: var(--text); }
.ds-copy { display: inline-block; position: relative; vertical-align: baseline; padding: 0; border: 0; background: none; font: inherit; color: inherit; cursor: pointer; border-radius: var(--radius-s); }
.ds-copy code { font-family: var(--font-mono); background: var(--bg); padding: 0.1em 0.3em; border: 1px solid transparent; border-radius: var(--radius-xs); }
.ds-copy:hover code, .ds-copy:focus-visible code { border-color: var(--accent); background: var(--accent-soft); color: var(--accent-strong); }
.ds-copy:focus-visible { outline: 2px solid var(--focus-ring); outline-offset: 2px; }
.ds-copy-icon { position: absolute; left: 100%; top: 50%; transform: translateY(-50%); margin-left: 0.15em; font-size: 0.85em; line-height: 1; color: var(--accent-strong); opacity: 0; pointer-events: none; }
.ds-copy:hover .ds-copy-icon, .ds-copy:focus-visible .ds-copy-icon { opacity: 1; }
@media (prefers-reduced-motion: no-preference) {
  .ds-copy code { transition: background var(--dur-quick) var(--ease-out), border-color var(--dur-quick) var(--ease-out), color var(--dur-quick) var(--ease-out); }
}

.ds-chip-row { display: flex; align-items: center; gap: var(--space-2); margin: 0; }
.ds-instance-chip { display: inline-flex; align-items: center; gap: 0.4em; font-family: var(--font-mono); font-size: var(--text-s); color: var(--accent-strong); background: var(--accent-soft); border: 1px solid var(--accent); border-radius: var(--radius-pill); padding: 0.15em 0.75em; align-self: flex-start; }
.ds-points { font-family: var(--font-mono); font-size: var(--text-xs); color: var(--text-muted); border: 1px solid var(--border); background: var(--bg); border-radius: var(--radius-pill); padding: 0.1em 0.55em; white-space: nowrap; }

.ds-timer { font-family: var(--font-mono); font-size: var(--text-l); font-weight: 700; font-variant-numeric: tabular-nums; letter-spacing: 0.03em; padding: 0.2em 0.6em; border-radius: var(--radius-s); background: var(--surface-raised); border: 1px solid var(--border); color: var(--accent-strong); }
.ds-timer-low { color: var(--danger); border-color: var(--danger); }
@media (prefers-reduced-motion: no-preference) {
  .ds-timer-low { animation: ds-timer-pulse 1.5s ease-in-out infinite; }
  @keyframes ds-timer-pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.55; } }
}
